export const GUA_64: GuaData[] = [
  { key: '111111', name: '乾', fullName: '乾为天', symbol: '☰', upperTrigram: '乾', lowerTrigram: '乾', wuxing: '金', guaci: '乾，元亨利贞。', guaciExplain: '乾卦象征天，具有创始、亨通、祥和、坚贞的德性。万物始于乾，刚健中正，自强不息。', yaoci: [{ position: 1, text: '初九：潜龙勿用。', explain: '龙潜伏在水中，暂不宜有所作为。时机未到，应韬光养晦。' }, { position: 2, text: '九二：见龙在田，利见大人。', explain: '龙出现在田野，利于见到大人物。才华初露，可得贵人相助。' }, { position: 3, text: '九三：君子终日乾乾，夕惕若，厉无咎。', explain: '君子整天勤勉努力，夜晚也保持警惕，虽有危险但无灾祸。' }, { position: 4, text: '九四：或跃在渊，无咎。', explain: '龙或跃起或退守深渊，没有灾祸。审时度势，进退有度。' }, { position: 5, text: '九五：飞龙在天，利见大人。', explain: '龙飞翔在天，利于见到大人物。事业鼎盛，大展宏图。' }, { position: 6, text: '上九：亢龙有悔。', explain: '龙飞得过高，会有悔恨。物极必反，盛极而衰。' }] },
  { key: '000000', name: '坤', fullName: '坤为地', symbol: '☷', upperTrigram: '坤', lowerTrigram: '坤', wuxing: '土', guaci: '坤，元亨，利牝马之贞。', guaciExplain: '坤卦象征地，具有柔顺、包容的德性。厚德载物，顺势而行。', yaoci: [{ position: 1, text: '初六：履霜，坚冰至。', explain: '踩到霜，坚冰将至。见微知著，防患未然。' }, { position: 2, text: '六二：直方大，不习无不利。', explain: '正直、方正、广大，不修习也无不顺利。' }, { position: 3, text: '六三：含章可贞。或从王事，无成有终。', explain: '蕴藏美德可以守正。从事王者之事，不求成功但有善终。' }, { position: 4, text: '六四：括囊，无咎无誉。', explain: '扎紧口袋，没有灾祸也没有赞誉。谨慎收敛。' }, { position: 5, text: '六五：黄裳，元吉。', explain: '穿黄色下裳，大吉。中正柔顺，美德显现。' }, { position: 6, text: '上六：龙战于野，其血玄黄。', explain: '龙在郊野战斗，流出玄黄色的血。阴极生阳，冲突将至。' }] },
  { key: '010001', name: '屯', fullName: '水雷屯', symbol: '☵☳', upperTrigram: '坎', lowerTrigram: '震', wuxing: '水', guaci: '屯，元亨利贞，勿用有攸往，利建侯。', guaciExplain: '屯卦象征初生，万物始生之时，充满艰难但前景光明。创业维艰，需坚持。', yaoci: [{ position: 1, text: '初九：磐桓，利居贞，利建侯。', explain: '徘徊不前，利于坚守正道，利于建立诸侯。' }, { position: 2, text: '六二：屯如邅如，乘马班如。匪寇婚媾，女子贞不字，十年乃字。', explain: '艰难徘徊，骑马转圈。不是强盗而是求婚，女子守贞不嫁，十年后才嫁。' }, { position: 3, text: '六三：即鹿无虞，惟入于林中，君子几不如舍，往吝。', explain: '追鹿没有向导，只身入林中，君子不如放弃，前往会有遗憾。' }, { position: 4, text: '六四：乘马班如，求婚媾，往吉，无不利。', explain: '骑马徘徊，前往求婚，吉利，无不顺利。' }, { position: 5, text: '九五：屯其膏，小贞吉，大贞凶。', explain: '囤积恩泽，小事守正则吉，大事守正则凶。' }, { position: 6, text: '上六：乘马班如，泣血涟如。', explain: '骑马徘徊，哭泣流血不止。极度悲伤。' }] },
  { key: '100010', name: '蒙', fullName: '山水蒙', symbol: '☶☵', upperTrigram: '艮', lowerTrigram: '坎', wuxing: '土', guaci: '蒙，亨。匪我求童蒙，童蒙求我。', guaciExplain: '蒙卦象征启蒙，教育之道。应当主动求教，而非强加于人。', yaoci: [{ position: 1, text: '初六：发蒙，利用刑人，用说桎梏，以往吝。', explain: '启发蒙昧，利于用刑罚规范人，脱去枷锁，继续前进会有遗憾。' }, { position: 2, text: '九二：包蒙吉。纳妇吉。子克家。', explain: '包容蒙昧则吉。娶妻则吉。儿子能治理家事。' }, { position: 3, text: '六三：勿用取女，见金夫，不有躬，无攸利。', explain: '不要娶这样的女子，见到有钱的男人就失身，无所利。' }, { position: 4, text: '六四：困蒙，吝。', explain: '困于蒙昧，遗憾。' }, { position: 5, text: '六五：童蒙，吉。', explain: '蒙昧的孩童，吉利。虚心求教。' }, { position: 6, text: '上九：击蒙，不利为寇，利御寇。', explain: '击破蒙昧，不利于做强盗，利于抵御强盗。' }] },
  { key: '010111', name: '需', fullName: '水天需', symbol: '☵☰', upperTrigram: '坎', lowerTrigram: '乾', wuxing: '水', guaci: '需，有孚，光亨，贞吉。利涉大川。', guaciExplain: '需卦象征等待，诚信则光明亨通，守正则吉。耐心等待时机。', yaoci: [{ position: 1, text: '初九：需于郊，利用恒，无咎。', explain: '在郊野等待，利于保持恒心，没有灾祸。' }, { position: 2, text: '九二：需于沙，小有言，终吉。', explain: '在沙地等待，稍有言语纷争，最终吉利。' }, { position: 3, text: '九三：需于泥，致寇至。', explain: '在泥泞中等待，招致强盗到来。' }, { position: 4, text: '六四：需于血，出自穴。', explain: '在血泊中等待，从洞穴中逃出。' }, { position: 5, text: '九五：需于酒食，贞吉。', explain: '在酒食中等待，守正则吉。' }, { position: 6, text: '上六：入于穴，有不速之客三人来，敬之终吉。', explain: '进入洞穴，有三位不速之客到来，恭敬对待最终吉利。' }] },
  { key: '111010', name: '讼', fullName: '天水讼', symbol: '☰☵', upperTrigram: '乾', lowerTrigram: '坎', wuxing: '金', guaci: '讼，有孚，窒惕，中吉，终凶。利见大人，不利涉大川。', guaciExplain: '讼卦象征争讼，有诚信但受阻，警惕则中途吉利，最终凶险。', yaoci: [{ position: 1, text: '初六：不永所事，小有言，终吉。', explain: '不长久纠缠争讼之事，稍有言语纷争，最终吉利。' }, { position: 2, text: '九二：不克讼，归而逋，其邑人三百户，无眚。', explain: '争讼不胜，回来逃匿，其邑中三百户人家没有灾祸。' }, { position: 3, text: '六三：食旧德，贞厉，终吉。或从王事，无成。', explain: '依靠旧有德行生活，守正防危，最终吉利。或从事王者之事，不求成功。' }, { position: 4, text: '九四：不克讼，复即命渝，安贞吉。', explain: '争讼不胜，回来改变初衷，安于守正则吉。' }, { position: 5, text: '九五：讼，元吉。', explain: '争讼，大吉。得公正裁决。' }, { position: 6, text: '上九：或锡之鞶带，终朝三褫之。', explain: '或许赐予大带，但一个早晨就被剥夺三次。' }] },
  { key: '000010', name: '师', fullName: '地水师', symbol: '☷☵', upperTrigram: '坤', lowerTrigram: '坎', wuxing: '土', guaci: '师，贞，丈人吉，无咎。', guaciExplain: '师卦象征军队，守正道，有德长者统帅则吉，无灾祸。', yaoci: [{ position: 1, text: '初六：师出以律，否臧凶。', explain: '军队出动要有纪律，否则凶险。' }, { position: 2, text: '九二：在师中吉，无咎，王三锡命。', explain: '在军中守中道则吉，无灾祸，君王多次赐命。' }, { position: 3, text: '六三：师或舆尸，凶。', explain: '军队或许会载尸而归，凶险。' }, { position: 4, text: '六四：师左次，无咎。', explain: '军队向左撤退，没有灾祸。' }, { position: 5, text: '六五：田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。', explain: '田中有猎物，利于捕获，无灾祸。长子统帅军队，次子载尸而归，守正亦凶。' }, { position: 6, text: '上六：大君有命，开国承家，小人勿用。', explain: '大君论功行赏，封邦建国，不要任用小人。' }] },
  { key: '010000', name: '比', fullName: '水地比', symbol: '☵☷', upperTrigram: '坎', lowerTrigram: '坤', wuxing: '水', guaci: '比，吉。原筮元永贞，无咎。不宁方来，后夫凶。', guaciExplain: '比卦象征亲辅，吉利。考察后守正则无灾祸。迟来者凶。', yaoci: [{ position: 1, text: '初六：有孚比之，无咎。有孚盈缶，终来有它，吉。', explain: '有诚信地亲辅，无灾祸。诚信如满缶之水，终有他福，吉利。' }, { position: 2, text: '六二：比之自内，贞吉。', explain: '从内部亲辅，守正则吉。' }, { position: 3, text: '六三：比之匪人。', explain: '亲辅不当之人。' }, { position: 4, text: '六四：外比之，贞吉。', explain: '从外部亲辅，守正则吉。' }, { position: 5, text: '九五：显比，王用三驱，失前禽。邑人不诫，吉。', explain: '光明正大地亲辅，君王三面驱猎，放走前面的猎物。邑人不须告诫，吉利。' }, { position: 6, text: '上六：比之无首，凶。', explain: '亲辅而没有开始，凶险。' }] },
  { key: '111011', name: '小畜', fullName: '风天小畜', symbol: '☴☰', upperTrigram: '巽', lowerTrigram: '乾', wuxing: '木', guaci: '小畜，亨。密云不雨，自我西郊。', guaciExplain: '小畜卦象征小有积蓄，亨通。密云不雨，力量尚不足以成大事。', yaoci: [{ position: 1, text: '初九：复自道，何其咎，吉。', explain: '从正道返回，有什么灾祸呢？吉利。' }, { position: 2, text: '九二：牵复，吉。', explain: '被牵连而返回，吉利。' }, { position: 3, text: '九三：舆说辐，夫妻反目。', explain: '车辐脱落，夫妻反目。' }, { position: 4, text: '六四：有孚，血去惕出，无咎。', explain: '有诚信，远离血光，脱离恐惧，无灾祸。' }, { position: 5, text: '九五：有孚挛如，富以其邻。', explain: '有诚信紧密相连，与邻居共享富裕。' }, { position: 6, text: '上九：既雨既处，尚德载，妇贞厉。月几望，君子征凶。', explain: '雨已下已停，尚可积德载物，妇人守正防危。月近圆时，君子出征凶险。' }] },
  { key: '110111', name: '履', fullName: '天泽履', symbol: '☰☱', upperTrigram: '乾', lowerTrigram: '兑', wuxing: '金', guaci: '履虎尾，不咥人，亨。', guaciExplain: '履卦象征践行，踩到虎尾，虎不咬人，亨通。小心行事则通。', yaoci: [{ position: 1, text: '初九：素履，往无咎。', explain: '以朴素的态度行事，前往无灾祸。' }, { position: 2, text: '九二：履道坦坦，幽人贞吉。', explain: '行走在平坦的大道上，隐士守正则吉。' }, { position: 3, text: '六三：眇能视，跛能履，履虎尾，咥人，凶。武人为于大君。', explain: '瞎了却要看，跛了却要走，踩到虎尾被咬，凶险。武人为大君效力。' }, { position: 4, text: '九四：履虎尾，愬愬终吉。', explain: '踩到虎尾，恐惧谨慎，最终吉利。' }, { position: 5, text: '九五：夬履，贞厉。', explain: '果断地行事，守正防危。' }, { position: 6, text: '上九：视履考祥，其旋元吉。', explain: '审视行为考察吉凶，回旋则大吉。' }] },
  { key: '000111', name: '泰', fullName: '地天泰', symbol: '☷☰', upperTrigram: '坤', lowerTrigram: '乾', wuxing: '土', guaci: '泰，小往大来，吉亨。', guaciExplain: '泰卦象征通达，小的去大的来，吉利亨通。天地交泰，万物通达。', yaoci: [{ position: 1, text: '初九：拔茅茹，以其汇，征吉。', explain: '拔起茅草及其同类，出征吉利。' }, { position: 2, text: '九二：包荒，用冯河，不遐遗，朋亡，得尚于中行。', explain: '包容广大，徒步渡河，不遗远者，不结朋党，中道而行。' }, { position: 3, text: '九三：无平不陂，无往不复，艰贞无咎。勿恤其孚，于食有福。', explain: '没有平地不变成斜坡，没有去了不回来的，艰难守正无灾祸。不必忧虑诚信，饮食有福。' }, { position: 4, text: '六四：翩翩不富，以其邻，不戒以孚。', explain: '翩翩而来不富有，与邻居相处，不须告诫而有诚信。' }, { position: 5, text: '六五：帝乙归妹，以祉元吉。', explain: '帝乙嫁女，以此得福大吉。' }, { position: 6, text: '上六：城复于隍，勿用师。自邑告命，贞吝。', explain: '城墙倒塌在干涸的护城河中，不要出兵。从邑中传来命令，守正亦遗憾。' }] },
  { key: '111000', name: '否', fullName: '天地否', symbol: '☰☷', upperTrigram: '乾', lowerTrigram: '坤', wuxing: '金', guaci: '否之匪人，不利君子贞，大往小来。', guaciExplain: '否卦象征闭塞，不利于君子守正，大的去小的来。天地不交，万物不通。', yaoci: [{ position: 1, text: '初六：拔茅茹，以其汇，贞吉亨。', explain: '拔起茅草及其同类，守正则吉亨。' }, { position: 2, text: '六二：包承。小人吉，大人否亨。', explain: '包容承顺。小人吉利，大人闭塞但终亨通。' }, { position: 3, text: '六三：包羞。', explain: '包容羞辱。' }, { position: 4, text: '九四：有命无咎，畴离祉。', explain: '有天命无灾祸，众人分享福祉。' }, { position: 5, text: '九五：休否，大人吉。其亡其亡，系于苞桑。', explain: '休止闭塞，大人吉利。时刻警惕灭亡，才能像系在丛生的桑树上一样稳固。' }, { position: 6, text: '上九：倾否，先否后喜。', explain: '倾覆闭塞，先闭塞后喜悦。' }] },
  { key: '101111', name: '同人', fullName: '天火同人', symbol: '☰☲', upperTrigram: '乾', lowerTrigram: '离', wuxing: '金', guaci: '同人于野，亨。利涉大川，利君子贞。', guaciExplain: '同人卦象征与人同心，在旷野中与人同心，亨通。利于渡大河，利于君子守正。', yaoci: [{ position: 1, text: '初九：同人于门，无咎。', explain: '在门外与人同心，无灾祸。' }, { position: 2, text: '六二：同人于宗，吝。', explain: '在宗族内与人同心，遗憾。' }, { position: 3, text: '九三：伏戎于莽，升其高陵，三岁不兴。', explain: '在草丛中埋伏军队，登上高陵，三年不能兴兵。' }, { position: 4, text: '九四：乘其墉，弗克攻，吉。', explain: '登上城墙，不能攻下，吉利。' }, { position: 5, text: '九五：同人，先号咷而后笑。大师克相遇。', explain: '与人同心，先大哭后大笑。大军战胜后相遇。' }, { position: 6, text: '上九：同人于郊，无悔。', explain: '在郊野与人同心，没有悔恨。' }] },
  { key: '111101', name: '大有', fullName: '火天大有', symbol: '☲☰', upperTrigram: '离', lowerTrigram: '乾', wuxing: '火', guaci: '大有，元亨。', guaciExplain: '大有卦象征大丰收，大亨通。富有天下，光明正大。', yaoci: [{ position: 1, text: '初九：无交害，匪咎，艰则无咎。', explain: '没有交往之害，不是灾祸，艰难则无灾祸。' }, { position: 2, text: '九二：大车以载，有攸往，无咎。', explain: '用大车装载，有所前往，无灾祸。' }, { position: 3, text: '九三：公用亨于天子，小人弗克。', explain: '公侯向天子进献贡品，小人不能做到。' }, { position: 4, text: '九四：匪其彭，无咎。', explain: '不炫耀其盛大，无灾祸。' }, { position: 5, text: '六五：厥孚交如，威如，吉。', explain: '其诚信交相辉映，威严庄重，吉利。' }, { position: 6, text: '上九：自天佑之，吉无不利。', explain: '上天保佑，吉利无不顺利。' }] },
  { key: '000100', name: '谦', fullName: '地山谦', symbol: '☷☶', upperTrigram: '坤', lowerTrigram: '艮', wuxing: '土', guaci: '谦，亨，君子有终。', guaciExplain: '谦卦象征谦虚，亨通，君子有好的结果。满招损，谦受益。', yaoci: [{ position: 1, text: '初六：谦谦君子，用涉大川，吉。', explain: '谦而又谦的君子，用以渡大河，吉利。' }, { position: 2, text: '六二：鸣谦，贞吉。', explain: '谦虚而闻名，守正则吉。' }, { position: 3, text: '九三：劳谦，君子有终，吉。', explain: '有功劳而谦虚，君子有好的结果，吉利。' }, { position: 4, text: '六四：无不利，撝谦。', explain: '无不顺利，发挥谦虚的美德。' }, { position: 5, text: '六五：不富以其邻，利用侵伐，无不利。', explain: '不富有是因为与邻居分享，利于出征讨伐，无不顺利。' }, { position: 6, text: '上六：鸣谦，利用行师，征邑国。', explain: '谦虚而闻名，利于出兵，征讨邑国。' }] },
  { key: '100000', name: '豫', fullName: '雷地豫', symbol: '☳☷', upperTrigram: '震', lowerTrigram: '坤', wuxing: '木', guaci: '豫，利建侯行师。', guaciExplain: '豫卦象征欢乐，利于建立诸侯和出兵。和乐豫悦，顺势而动。', yaoci: [{ position: 1, text: '初六：鸣豫，凶。', explain: '自鸣得意地享乐，凶险。' }, { position: 2, text: '六二：介于石，不终日，贞吉。', explain: '坚如磐石，不过整天就觉悟，守正则吉。' }, { position: 3, text: '六三：盱豫，悔。迟有悔。', explain: '献媚求乐，有悔恨。迟疑更有悔恨。' }, { position: 4, text: '九四：由豫，大有得。勿疑。朋盍簪。', explain: '由此而欢乐，大有收获。不要疑虑。朋友聚会。' }, { position: 5, text: '六五：贞疾，恒不死。', explain: '守正防疾，长久不死。' }, { position: 6, text: '上六：冥豫，成有渝，无咎。', explain: '昏冥享乐，事成而有改变，无灾祸。' }] },
  { key: '001011', name: '随', fullName: '泽雷随', symbol: '☱☳', upperTrigram: '兑', lowerTrigram: '震', wuxing: '金', guaci: '随，元亨利贞，无咎。', guaciExplain: '随卦象征随从，大亨通，利于守正，无灾祸。随机应变，顺势而为。', yaoci: [{ position: 1, text: '初九：官有渝，贞吉。出门交有功。', explain: '官事有变化，守正则吉。出门交往有功。' }, { position: 2, text: '六二：系小子，失丈夫。', explain: '依附小人，失去大人。' }, { position: 3, text: '六三：系丈夫，失小子。随有求得，利居贞。', explain: '依附大人，失去小人。随从而有所求必得，利于安守正道。' }, { position: 4, text: '九四：随有获，贞凶。有孚在道，以明，何咎。', explain: '随从而有收获，守正防凶。有诚信行于正道，光明磊落，有何灾祸。' }, { position: 5, text: '九五：孚于嘉，吉。', explain: '对善人诚信，吉利。' }, { position: 6, text: '上六：拘系之，乃从维之。王用亨于西山。', explain: '拘禁起来，又从而释放。君王在西山祭祀。' }] },
  { key: '110100', name: '蛊', fullName: '山风蛊', symbol: '☶☴', upperTrigram: '艮', lowerTrigram: '巽', wuxing: '土', guaci: '蛊，元亨，利涉大川。先甲三日，后甲三日。', guaciExplain: '蛊卦象征整治败坏，大亨通，利于渡大河。改革需择时。', yaoci: [{ position: 1, text: '初六：干父之蛊，有子，考无咎，厉终吉。', explain: '纠正父亲的过失，有这样的儿子，父亲无灾祸，虽有危险最终吉利。' }, { position: 2, text: '九二：干母之蛊，不可贞。', explain: '纠正母亲的过失，不可固执。' }, { position: 3, text: '九三：干父之蛊，小有悔，无大咎。', explain: '纠正父亲的过失，稍有悔恨，无大灾祸。' }, { position: 4, text: '六四：裕父之蛊，往见吝。', explain: '宽容父亲的过失，前往会有遗憾。' }, { position: 5, text: '六五：干父之蛊，用誉。', explain: '纠正父亲的过失，受到赞誉。' }, { position: 6, text: '上九：不事王侯，高尚其事。', explain: '不侍奉王侯，高尚自己的志向。' }] },
  { key: '010011', name: '临', fullName: '地泽临', symbol: '☷☱', upperTrigram: '坤', lowerTrigram: '兑', wuxing: '土', guaci: '临，元亨利贞。至于八月有凶。', guaciExplain: '临卦象征面临，大亨通利于守正。但到八月有凶险。居安思危。', yaoci: [{ position: 1, text: '初九：咸临，贞吉。', explain: '以感化面临，守正则吉。' }, { position: 2, text: '九二：咸临，吉无不利。', explain: '以感化面临，吉利无不顺利。' }, { position: 3, text: '六三：甘临，无攸利。既忧之，无咎。', explain: '以甜言蜜语面临，无所利。已经忧虑此事，无灾祸。' }, { position: 4, text: '六四：至临，无咎。', explain: '亲自面临，无灾祸。' }, { position: 5, text: '六五：知临，大君之宜，吉。', explain: '以明智面临，是大君的适宜做法，吉利。' }, { position: 6, text: '上六：敦临，吉无咎。', explain: '以敦厚面临，吉利无灾祸。' }] },
  { key: '110000', name: '观', fullName: '风地观', symbol: '☴☷', upperTrigram: '巽', lowerTrigram: '坤', wuxing: '木', guaci: '观，盥而不荐，有孚颙若。', guaciExplain: '观卦象征观察，祭祀时只看灌酒仪式而不看献牲，有诚信而敬仰。', yaoci: [{ position: 1, text: '初六：童观，小人无咎，君子吝。', explain: '像孩童一样观察，小人无灾祸，君子有遗憾。' }, { position: 2, text: '六二：窥观，利女贞。', explain: '从门缝中观察，利于女子守正。' }, { position: 3, text: '六三：观我生，进退。', explain: '观察自己的生存状态，决定进退。' }, { position: 4, text: '六四：观国之光，利用宾于王。', explain: '观察国家的光辉，利于做君王的宾客。' }, { position: 5, text: '九五：观我生，君子无咎。', explain: '观察自己的生存状态，君子无灾祸。' }, { position: 6, text: '上九：观其生，君子无咎。', explain: '观察他人的生存状态，君子无灾祸。' }] },
  { key: '101001', name: '噬嗑', fullName: '火雷噬嗑', symbol: '☲☳', upperTrigram: '离', lowerTrigram: '震', wuxing: '火', guaci: '噬嗑，亨。利用狱。', guaciExplain: '噬嗑卦象征咬合，亨通。利于使用刑罚。明罚敕法。', yaoci: [{ position: 1, text: '初九：屦校灭趾，无咎。', explain: '脚上戴着刑具遮住脚趾，无灾祸。' }, { position: 2, text: '六二：噬肤灭鼻，无咎。', explain: '咬肥肉遮住鼻子，无灾祸。' }, { position: 3, text: '六三：噬腊肉，遇毒，小吝，无咎。', explain: '咬腊肉遇到毒，稍有遗憾，无灾祸。' }, { position: 4, text: '九四：噬干胏，得金矢，利艰贞，吉。', explain: '咬带骨的干肉得到铜箭头，利于艰难守正，吉利。' }, { position: 5, text: '六五：噬干肉，得黄金，贞厉，无咎。', explain: '咬干肉得到黄金，守正防危，无灾祸。' }, { position: 6, text: '上九：何校灭耳，凶。', explain: '肩上扛着刑具遮住耳朵，凶险。' }] },
  { key: '100101', name: '贲', fullName: '山火贲', symbol: '☶☲', upperTrigram: '艮', lowerTrigram: '离', wuxing: '土', guaci: '贲，亨。小利有攸往。', guaciExplain: '贲卦象征文饰，亨通。有小利可前往。文质彬彬。', yaoci: [{ position: 1, text: '初九：贲其趾，舍车而徒。', explain: '文饰脚趾，舍弃车子步行。' }, { position: 2, text: '六二：贲其须。', explain: '文饰胡须。' }, { position: 3, text: '九三：贲如濡如，永贞吉。', explain: '文饰润泽，长久守正则吉。' }, { position: 4, text: '六四：贲如皤如，白马翰如，匪寇婚媾。', explain: '文饰洁白，白马如飞，不是强盗而是求婚。' }, { position: 5, text: '六五：贲于丘园，束帛戋戋，吝，终吉。', explain: '文饰山丘园林，束帛微薄，虽有遗憾，最终吉利。' }, { position: 6, text: '上九：白贲，无咎。', explain: '以白色文饰，无灾祸。返璞归真。' }] },
  { key: '100000', name: '剥', fullName: '山地剥', symbol: '☶☷', upperTrigram: '艮', lowerTrigram: '坤', wuxing: '土', guaci: '剥，不利有攸往。', guaciExplain: '剥卦象征剥落，不利于有所前往。阴盛阳衰，不宜妄动。', yaoci: [{ position: 1, text: '初六：剥床以足，蔑贞凶。', explain: '剥落床脚，轻视守正则凶。' }, { position: 2, text: '六二：剥床以辨，蔑贞凶。', explain: '剥落床板，轻视守正则凶。' }, { position: 3, text: '六三：剥之，无咎。', explain: '剥落它，无灾祸。' }, { position: 4, text: '六四：剥床以肤，凶。', explain: '剥落到床面，凶险。' }, { position: 5, text: '六五：贯鱼，以宫人宠，无不利。', explain: '像鱼贯而入一样，以宫人受宠，无不顺利。' }, { position: 6, text: '上九：硕果不食，君子得舆，小人剥庐。', explain: '大果实不吃，君子得到车子，小人剥去房屋。' }] },
  { key: '000001', name: '复', fullName: '地雷复', symbol: '☷☳', upperTrigram: '坤', lowerTrigram: '震', wuxing: '土', guaci: '复，亨。出入无疾，朋来无咎。反复其道，七日来复，利有攸往。', guaciExplain: '复卦象征复归，亨通。一阳来复，否极泰来。', yaoci: [{ position: 1, text: '初九：不远复，无祗悔，元吉。', explain: '走不远就返回，没有大悔恨，大吉。' }, { position: 2, text: '六二：休复，吉。', explain: '愉快地返回，吉利。' }, { position: 3, text: '六三：频复，厉无咎。', explain: '频繁地返回，有危险但无灾祸。' }, { position: 4, text: '六四：中行独复。', explain: '在行列中独自返回。' }, { position: 5, text: '六五：敦复，无悔。', explain: '敦厚地返回，没有悔恨。' }, { position: 6, text: '上六：迷复，凶，有灾眚。用行师，终有大败，以其国君凶，至于十年不克征。', explain: '迷失返回之路，凶险，有灾祸。出兵最终大败，国君凶险，十年不能出征。' }] },
  { key: '111001', name: '无妄', fullName: '天雷无妄', symbol: '☰☳', upperTrigram: '乾', lowerTrigram: '震', wuxing: '金', guaci: '无妄，元亨利贞。其匪正有眚，不利有攸往。', guaciExplain: '无妄卦象征不妄为，大亨通利于守正。不正则有灾祸。', yaoci: [{ position: 1, text: '初九：无妄，往吉。', explain: '不妄为，前往吉利。' }, { position: 2, text: '六二：不耕获，不菑畬，则利有攸往。', explain: '不耕种而收获，不开荒而得熟田，则利于前往。' }, { position: 3, text: '六三：无妄之灾，或系之牛，行人之得，邑人之灾。', explain: '不妄为却遭灾，有人拴着的牛，被行人牵走，邑人遭灾。' }, { position: 4, text: '九四：可贞，无咎。', explain: '可以守正，无灾祸。' }, { position: 5, text: '九五：无妄之疾，勿药有喜。', explain: '不妄为而得病，不用吃药会好。' }, { position: 6, text: '上九：无妄，行有眚，无攸利。', explain: '不妄为，行动有灾祸，无所利。' }] },
  { key: '100111', name: '大畜', fullName: '山天大畜', symbol: '☶☰', upperTrigram: '艮', lowerTrigram: '乾', wuxing: '土', guaci: '大畜，利贞，不家食吉，利涉大川。', guaciExplain: '大畜卦象征大有积蓄，利于守正，不在家吃饭则吉，利于渡大河。', yaoci: [{ position: 1, text: '初九：有厉利已。', explain: '有危险利于停止。' }, { position: 2, text: '九二：舆说辐。', explain: '车辐脱落。' }, { position: 3, text: '九三：良马逐，利艰贞。日闲舆卫，利有攸往。', explain: '良马追逐，利于艰难守正。每日练习车马防卫，利于前往。' }, { position: 4, text: '六四：童牛之牿，元吉。', explain: '小牛角上绑的横木，大吉。' }, { position: 5, text: '六五：豶豕之牙，吉。', explain: '阉割的猪的牙齿，吉利。' }, { position: 6, text: '上九：何天之衢，亨。', explain: '何等广阔的天路，亨通。' }] },
  { key: '100001', name: '颐', fullName: '山雷颐', symbol: '☶☳', upperTrigram: '艮', lowerTrigram: '震', wuxing: '土', guaci: '颐，贞吉。观颐，自求口实。', guaciExplain: '颐卦象征颐养，守正则吉。观察颐养之道，自求口中之食。', yaoci: [{ position: 1, text: '初九：舍尔灵龟，观我朵颐，凶。', explain: '舍弃你的灵龟，看我大嚼，凶险。' }, { position: 2, text: '六二：颠颐，拂经，于丘颐，征凶。', explain: '颠倒颐养，违背常理，在山丘上求养，出征凶险。' }, { position: 3, text: '六三：拂颐，贞凶，十年勿用，无攸利。', explain: '违背颐养之道，守正亦凶，十年不可用，无所利。' }, { position: 4, text: '六四：颠颐吉，虎视眈眈，其欲逐逐，无咎。', explain: '颠倒颐养则吉，虎视眈眈，欲望追逐，无灾祸。' }, { position: 5, text: '六五：拂经，居贞吉，不可涉大川。', explain: '违背常理，安守正道则吉，不可渡大河。' }, { position: 6, text: '上九：由颐，厉吉，利涉大川。', explain: '由此颐养，有危险但吉利，利于渡大河。' }] },
  { key: '010010', name: '大过', fullName: '泽风大过', symbol: '☱☴', upperTrigram: '兑', lowerTrigram: '巽', wuxing: '金', guaci: '大过，栋桡，利有攸往，亨。', guaciExplain: '大过卦象征大过越，栋梁弯曲，利于前往，亨通。非常时期需非常手段。', yaoci: [{ position: 1, text: '初六：藉用白茅，无咎。', explain: '用白茅垫祭品，无灾祸。' }, { position: 2, text: '九二：枯杨生稊，老夫得其女妻，无不利。', explain: '枯杨树生新芽，老夫娶少妻，无不顺利。' }, { position: 3, text: '九三：栋桡，凶。', explain: '栋梁弯曲，凶险。' }, { position: 4, text: '九四：栋隆，吉。有它吝。', explain: '栋梁隆起，吉利。但有其他遗憾。' }, { position: 5, text: '九五：枯杨生华，老妇得其士夫，无咎无誉。', explain: '枯杨树开花，老妇嫁少夫，无灾祸无赞誉。' }, { position: 6, text: '上六：过涉灭顶，凶，无咎。', explain: '渡河淹没头顶，凶险，但无灾祸。' }] },
  { key: '010010', name: '坎', fullName: '坎为水', symbol: '☵☵', upperTrigram: '坎', lowerTrigram: '坎', wuxing: '水', guaci: '习坎，有孚，维心亨，行有尚。', guaciExplain: '坎卦象征重重险难，有诚信，维系心志亨通，行动会得到崇尚。', yaoci: [{ position: 1, text: '初六：习坎，入于坎窞，凶。', explain: '重险，陷入深坑，凶险。' }, { position: 2, text: '九二：坎有险，求小得。', explain: '险中有险，求小有所得。' }, { position: 3, text: '六三：来之坎坎，险且枕，入于坎窞，勿用。', explain: '来去皆险，危险且深，陷入深坑，不可用。' }, { position: 4, text: '六四：樽酒簋贰，用缶，纳约自牖，终无咎。', explain: '一樽酒两簋饭，用瓦器盛，从窗户送入简约之物，最终无灾祸。' }, { position: 5, text: '九五：坎不盈，祗既平，无咎。', explain: '险坑未满，只求平整，无灾祸。' }, { position: 6, text: '上六：系用徽纆，窴于丛棘，三岁不得，凶。', explain: '用绳索捆绑，放在荆棘丛中，三年不得解脱，凶险。' }] },
  { key: '101101', name: '离', fullName: '离为火', symbol: '☲☲', upperTrigram: '离', lowerTrigram: '离', wuxing: '火', guaci: '离，利贞，亨。畜牝牛，吉。', guaciExplain: '离卦象征附丽，利于守正，亨通。畜养母牛，吉利。光明依附。', yaoci: [{ position: 1, text: '初九：履错然，敬之无咎。', explain: '脚步错乱，恭敬对待无灾祸。' }, { position: 2, text: '六二：黄离，元吉。', explain: '黄色附丽，大吉。' }, { position: 3, text: '九三：日昃之离，不鼓缶而歌，则大耋之嗟，凶。', explain: '日偏西的附丽，不敲瓦盆唱歌，就是老人的叹息，凶险。' }, { position: 4, text: '九四：突如其来如，焚如，死如，弃如。', explain: '突然来临，焚烧，死亡，抛弃。' }, { position: 5, text: '六五：出涕沱若，戚嗟若，吉。', explain: '泪流如雨，悲伤叹息，吉利。' }, { position: 6, text: '上九：王用出征，有嘉折首，获匪其丑，无咎。', explain: '君王出征，嘉奖斩首者，俘获的不是其同类，无灾祸。' }] },
]

const REMAINING_GUAS: GuaData[] = [
  { key: '011100', name: '咸', fullName: '泽山咸', symbol: '☱☶', upperTrigram: '兑', lowerTrigram: '艮', wuxing: '金', guaci: '咸，亨，利贞，取女吉。', guaciExplain: '咸卦象征感应，亨通，利于守正，娶女吉利。', yaoci: [{ position: 1, text: '初六：咸其拇。', explain: '感应到脚拇指。' }, { position: 2, text: '六二：咸其腓，凶，居吉。', explain: '感应到小腿，凶险，安居则吉。' }, { position: 3, text: '九三：咸其股，执其随，往吝。', explain: '感应到大腿，执意跟随，前往有遗憾。' }, { position: 4, text: '九四：贞吉悔亡，憧憧往来，朋从尔思。', explain: '守正则吉悔恨消失，心神不定地往来，朋友顺从你的心思。' }, { position: 5, text: '九五：咸其脢，无悔。', explain: '感应到背脊，没有悔恨。' }, { position: 6, text: '上六：咸其辅颊舌。', explain: '感应到面颊和舌头。' }] },
  { key: '001110', name: '恒', fullName: '雷风恒', symbol: '☳☴', upperTrigram: '震', lowerTrigram: '巽', wuxing: '木', guaci: '恒，亨，无咎，利贞，利有攸往。', guaciExplain: '恒卦象征恒久，亨通，无灾祸，利于守正，利于前往。', yaoci: [{ position: 1, text: '初六：浚恒，贞凶，无攸利。', explain: '过分追求恒久，守正亦凶，无所利。' }, { position: 2, text: '九二：悔亡。', explain: '悔恨消失。' }, { position: 3, text: '九三：不恒其德，或承之羞，贞吝。', explain: '不能恒守其德，或许会承受羞辱，守正亦遗憾。' }, { position: 4, text: '九四：田无禽。', explain: '田猎没有猎物。' }, { position: 5, text: '六五：恒其德，贞，妇人吉，夫子凶。', explain: '恒守其德，守正，妇人吉利，男子凶险。' }, { position: 6, text: '上六：振恒，凶。', explain: '动摇恒久之道，凶险。' }] },
  { key: '000100', name: '遁', fullName: '天山遁', symbol: '☰☶', upperTrigram: '乾', lowerTrigram: '艮', wuxing: '金', guaci: '遁，亨，小利贞。', guaciExplain: '遁卦象征退避，亨通，小利于守正。', yaoci: [{ position: 1, text: '初六：遁尾，厉，勿用有攸往。', explain: '退避在末尾，危险，不要有所前往。' }, { position: 2, text: '六二：执之用黄牛之革，莫之胜说。', explain: '用黄牛皮绳捆绑，没有人能解开。' }, { position: 3, text: '九三：系遁，有疾厉，畜臣妾吉。', explain: '牵挂而退避，有疾病危险，畜养臣妾则吉。' }, { position: 4, text: '九四：好遁，君子吉，小人否。', explain: '喜好退避，君子吉利，小人不然。' }, { position: 5, text: '九五：嘉遁，贞吉。', explain: '嘉美的退避，守正则吉。' }, { position: 6, text: '上九：肥遁，无不利。', explain: '宽裕地退避，无不顺利。' }] },
  { key: '001111', name: '大壮', fullName: '雷天大壮', symbol: '☳☰', upperTrigram: '震', lowerTrigram: '乾', wuxing: '木', guaci: '大壮，利贞。', guaciExplain: '大壮卦象征大壮盛，利于守正。', yaoci: [{ position: 1, text: '初九：壮于趾，征凶，有孚。', explain: '脚趾壮盛，出征凶险，但有诚信。' }, { position: 2, text: '九二：贞吉。', explain: '守正则吉。' }, { position: 3, text: '九三：小人用壮，君子用罔，贞厉。羝羊触藩，羸其角。', explain: '小人用壮力，君子不用壮力，守正防危。公羊冲撞藩篱，卡住羊角。' }, { position: 4, text: '九四：贞吉悔亡，藩决不羸，壮于大舆之輹。', explain: '守正则吉悔恨消失，藩篱冲破不再卡住，壮盛如大车的车辐。' }, { position: 5, text: '六五：丧羊于易，无悔。', explain: '在田边丢失了羊，没有悔恨。' }, { position: 6, text: '上六：羝羊触藩，不能退，不能遂，无攸利，艰则吉。', explain: '公羊冲撞藩篱，不能退也不能进，无所利，艰难则吉。' }] },
  { key: '101000', name: '晋', fullName: '火地晋', symbol: '☲☷', upperTrigram: '离', lowerTrigram: '坤', wuxing: '火', guaci: '晋，康侯用锡马蕃庶，昼日三接。', guaciExplain: '晋卦象征前进，康侯用天子赐予的良马繁殖，一天之内三次接见。', yaoci: [{ position: 1, text: '初六：晋如，摧如，贞吉。罔孚，裕无咎。', explain: '前进又后退，守正则吉。尚未取得信任，宽裕则无灾祸。' }, { position: 2, text: '六二：晋如，愁如，贞吉。受兹介福，于其王母。', explain: '前进又忧愁，守正则吉。从王母那里接受大福。' }, { position: 3, text: '六三：众允，悔亡。', explain: '众人信任，悔恨消失。' }, { position: 4, text: '九四：晋如鼫鼠，贞厉。', explain: '前进如鼫鼠，守正防危。' }, { position: 5, text: '六五：悔亡，失得勿恤，往吉无不利。', explain: '悔恨消失，不要忧虑得失，前往吉利无不顺利。' }, { position: 6, text: '上九：晋其角，维用伐邑，厉吉无咎，贞吝。', explain: '前进到角尖，只能用来征伐邑国，危险但吉利无灾祸，守正亦遗憾。' }] },
  { key: '000101', name: '明夷', fullName: '地火明夷', symbol: '☷☲', upperTrigram: '坤', lowerTrigram: '离', wuxing: '土', guaci: '明夷，利艰贞。', guaciExplain: '明夷卦象征光明受伤，利于艰难守正。', yaoci: [{ position: 1, text: '初九：明夷于飞，垂其翼。君子于行，三日不食，有攸往，主人有言。', explain: '光明受伤如飞鸟垂翼。君子出行，三天不吃饭，有所前往，主人有言语。' }, { position: 2, text: '六二：明夷，夷于左股，用拯马壮，吉。', explain: '光明受伤，伤在左腿，用强壮的马拯救，吉利。' }, { position: 3, text: '九三：明夷于南狩，得其大首，不可疾贞。', explain: '光明受伤，到南方狩猎，获得大头目，不可急于守正。' }, { position: 4, text: '六四：入于左腹，获明夷之心，于出门庭。', explain: '进入左腹，获得光明受伤的内情，出门离去。' }, { position: 5, text: '六五：箕子之明夷，利贞。', explain: '箕子的光明受伤，利于守正。' }, { position: 6, text: '上六：不明晦，初登于天，后入于地。', explain: '不明而昏暗，起初升上天空，后来落入地下。' }] },
  { key: '110101', name: '家人', fullName: '风火家人', symbol: '☴☲', upperTrigram: '巽', lowerTrigram: '离', wuxing: '木', guaci: '家人，利女贞。', guaciExplain: '家人卦象征家庭，利于女子守正。', yaoci: [{ position: 1, text: '初九：闲有家，悔亡。', explain: '防闲于家，悔恨消失。' }, { position: 2, text: '六二：无攸遂，在中馈，贞吉。', explain: '无所成就，主管家中饮食，守正则吉。' }, { position: 3, text: '九三：家人嗃嗃，悔厉吉。妇子嘻嘻，终吝。', explain: '家人严厉，有悔恨有危险但吉利。妇孺嬉笑，最终遗憾。' }, { position: 4, text: '六四：富家，大吉。', explain: '使家庭富裕，大吉。' }, { position: 5, text: '九五：王假有家，勿恤，吉。', explain: '君王来到家中，不要忧虑，吉利。' }, { position: 6, text: '上九：有孚威如，终吉。', explain: '有诚信且威严，最终吉利。' }] },
  { key: '101011', name: '睽', fullName: '火泽睽', symbol: '☲☱', upperTrigram: '离', lowerTrigram: '兑', wuxing: '火', guaci: '睽，小事吉。', guaciExplain: '睽卦象征背离，小事吉利。', yaoci: [{ position: 1, text: '初九：悔亡，丧马勿逐，自复。见恶人无咎。', explain: '悔恨消失，丢失马不要追，自己会回来。见到恶人无灾祸。' }, { position: 2, text: '九二：遇主于巷，无咎。', explain: '在小巷中遇到主人，无灾祸。' }, { position: 3, text: '六三：见舆曳，其牛掣，其人天且劓。无初有终。', explain: '看到大车被拖，牛被牵制，那人受了墨刑和劓刑。开始不好最终好。' }, { position: 4, text: '九四：睽孤，遇元夫，交孚，厉无咎。', explain: '孤独背离，遇到善人，以诚信相交，有危险但无灾祸。' }, { position: 5, text: '六五：悔亡，厥宗噬肤，往何咎。', explain: '悔恨消失，同宗之人吃肉，前往有何灾祸。' }, { position: 6, text: '上九：睽孤，见豕负涂，载鬼一车，先张之弧，后说之弧，匪寇婚媾，往遇雨则吉。', explain: '孤独背离，看到猪满身泥，载着一车鬼，先张弓后放下弓，不是强盗而是求婚，前往遇雨则吉。' }] },
  { key: '010001', name: '蹇', fullName: '水山蹇', symbol: '☵☶', upperTrigram: '坎', lowerTrigram: '艮', wuxing: '水', guaci: '蹇，利西南，不利东北，利见大人，贞吉。', guaciExplain: '蹇卦象征困难，利于西南，不利于东北，利于见到大人，守正则吉。', yaoci: [{ position: 1, text: '初六：往蹇，来誉。', explain: '前往有困难，回来有赞誉。' }, { position: 2, text: '六二：王臣蹇蹇，匪躬之故。', explain: '王臣历尽艰难，不是为了自身。' }, { position: 3, text: '九三：往蹇来反。', explain: '前往有困难，回来。' }, { position: 4, text: '六四：往蹇来连。', explain: '前往有困难，回来联合。' }, { position: 5, text: '九五：大蹇朋来。', explain: '大困难中朋友来助。' }, { position: 6, text: '上六：往蹇来硕，吉，利见大人。', explain: '前往有困难，回来有大收获，吉利，利于见到大人。' }] },
  { key: '100010', name: '解', fullName: '雷水解', symbol: '☳☵', upperTrigram: '震', lowerTrigram: '坎', wuxing: '木', guaci: '解，利西南，无所往，其来复吉。有攸往，夙吉。', guaciExplain: '解卦象征解除困难，利于西南，无所前往则回来吉利，有所前往则早吉。', yaoci: [{ position: 1, text: '初六：无咎。', explain: '无灾祸。' }, { position: 2, text: '九二：田获三狐，得黄矢，贞吉。', explain: '田猎获得三只狐狸，得到铜箭头，守正则吉。' }, { position: 3, text: '六三：负且乘，致寇至，贞吝。', explain: '背着东西坐车，招致强盗到来，守正亦遗憾。' }, { position: 4, text: '九四：解而拇，朋至斯孚。', explain: '解开脚拇指，朋友到来以诚信相待。' }, { position: 5, text: '六五：君子维有解，吉。有孚于小人。', explain: '君子只有解除困难才吉。对小人也要有诚信。' }, { position: 6, text: '上六：公用射隼，于高墉之上，获之无不利。', explain: '公侯射杀隼鸟，在高墙之上，获得它无不顺利。' }] },
  { key: '110001', name: '损', fullName: '山泽损', symbol: '☶☱', upperTrigram: '艮', lowerTrigram: '兑', wuxing: '土', guaci: '损，有孚，元吉，无咎，可贞，利有攸往。', guaciExplain: '损卦象征减损，有诚信则大吉，无灾祸，可守正，利于前往。', yaoci: [{ position: 1, text: '初九：已事遄往，无咎，酌损之。', explain: '完成事情赶快前往，无灾祸，酌情减损。' }, { position: 2, text: '九二：利贞，征凶，弗损益之。', explain: '利于守正，出征凶险，不减损而增益。' }, { position: 3, text: '六三：三人行则损一人，一人行则得其友。', explain: '三人同行则减损一人，一人独行则得到朋友。' }, { position: 4, text: '六四：损其疾，使遄有喜，无咎。', explain: '减损疾病，使人赶快有喜，无灾祸。' }, { position: 5, text: '六五：或益之，十朋之龟弗克违，元吉。', explain: '有人增益，十朋之龟也不能违背，大吉。' }, { position: 6, text: '上九：弗损益之，无咎，贞吉，利有攸往，得臣无家。', explain: '不减损而增益，无灾祸，守正则吉，利于前往，得到臣属没有家室。' }] },
  { key: '100110', name: '益', fullName: '风雷益', symbol: '☴☳', upperTrigram: '巽', lowerTrigram: '震', wuxing: '木', guaci: '益，利有攸往，利涉大川。', guaciExplain: '益卦象征增益，利于前往，利于渡大河。', yaoci: [{ position: 1, text: '初九：利用为大作，元吉，无咎。', explain: '利于做大事，大吉，无灾祸。' }, { position: 2, text: '六二：或益之，十朋之龟弗克违，永贞吉。王用享于帝，吉。', explain: '有人增益，十朋之龟也不能违背，长久守正则吉。君王祭祀天帝，吉利。' }, { position: 3, text: '六三：益之用凶事，无咎。有孚中行，告公用圭。', explain: '增益用于凶事，无灾祸。有诚信中道而行，用圭璧告知公侯。' }, { position: 4, text: '六四：中行，告公从。利用为依迁国。', explain: '中道而行，告知公侯获从。利于迁都。' }, { position: 5, text: '九五：有孚惠心，勿问元吉。有孚惠我德。', explain: '有诚信施惠之心，不必问大吉。有诚信施惠于我的德行。' }, { position: 6, text: '上九：莫益之，或击之，立心勿恒，凶。', explain: '没有人增益，有人攻击，立心不恒久，凶险。' }] },
  { key: '111110', name: '夬', fullName: '泽天夬', symbol: '☱☰', upperTrigram: '兑', lowerTrigram: '乾', wuxing: '金', guaci: '夬，扬于王庭，孚号，有厉，告自邑，不利即戎，利有攸往。', guaciExplain: '夬卦象征决断，在王庭上宣扬，诚信号令，有危险，从邑中告知，不利于立即用兵，利于前往。', yaoci: [{ position: 1, text: '初九：壮于前趾，往不胜为咎。', explain: '前脚趾壮盛，前往不能取胜则为灾祸。' }, { position: 2, text: '九二：惕号，莫夜有戎，勿恤。', explain: '警惕号令，夜间有兵戎之事，不要忧虑。' }, { position: 3, text: '九三：壮于頄，有凶。君子夬夬，独行遇雨，若濡有愠，无咎。', explain: '颧骨壮盛，有凶险。君子果断决断，独行遇雨，虽淋湿而恼怒，无灾祸。' }, { position: 4, text: '九四：臀无肤，其行次且。牵羊悔亡，闻言不信。', explain: '臀部没有皮肤，行走困难。牵羊则悔恨消失，听到话却不信。' }, { position: 5, text: '九五：苋陆夬夬，中行无咎。', explain: '像苋陆一样果断决断，中道而行无灾祸。' }, { position: 6, text: '上六：无号，终有凶。', explain: '没有号令，最终有凶险。' }] },
  { key: '011111', name: '姤', fullName: '天风姤', symbol: '☰☴', upperTrigram: '乾', lowerTrigram: '巽', wuxing: '金', guaci: '姤，女壮，勿用取女。', guaciExplain: '姤卦象征相遇，女子壮盛，不要娶这样的女子。', yaoci: [{ position: 1, text: '初六：系于金柅，贞吉，有攸往，见凶，羸豕孚蹢躅。', explain: '系在铜制刹车上，守正则吉，有所前往，见到凶险，瘦弱的猪也在躁动。' }, { position: 2, text: '九二：包有鱼，无咎，不利宾。', explain: '厨房有鱼，无灾祸，不利于招待宾客。' }, { position: 3, text: '九三：臀无肤，其行次且，厉，无大咎。', explain: '臀部没有皮肤，行走困难，有危险，无大灾祸。' }, { position: 4, text: '九四：包无鱼，起凶。', explain: '厨房没有鱼，凶险将起。' }, { position: 5, text: '九五：以杞包瓜，含章，有陨自天。', explain: '用杞柳包瓜，含藏文采，有好事从天而降。' }, { position: 6, text: '上九：姤其角，吝，无咎。', explain: '遇到角尖，遗憾，无灾祸。' }] },
  { key: '000110', name: '萃', fullName: '泽地萃', symbol: '☱☷', upperTrigram: '兑', lowerTrigram: '坤', wuxing: '金', guaci: '萃，亨。王假有庙，利见大人，亨，利贞。用大牲吉，利有攸往。', guaciExplain: '萃卦象征聚集，亨通。君王来到宗庙，利于见到大人，亨通，利于守正。用大牲祭祀吉利，利于前往。', yaoci: [{ position: 1, text: '初六：有孚不终，乃乱乃萃，若号，一握为笑，勿恤，往无咎。', explain: '有诚信不能坚持，于是混乱于是聚集，如果号哭，一握之间转为欢笑，不要忧虑，前往无灾祸。' }, { position: 2, text: '六二：引吉，无咎，孚乃利用禴。', explain: '引导则吉，无灾祸，有诚信则利于薄祭。' }, { position: 3, text: '六三：萃如，嗟如，无攸利，往无咎，小吝。', explain: '聚集的样子，叹息的样子，无所利，前往无灾祸，稍有遗憾。' }, { position: 4, text: '九四：大吉，无咎。', explain: '大吉，无灾祸。' }, { position: 5, text: '九五：萃有位，无咎。匪孚，元永贞，悔亡。', explain: '聚集而有地位，无灾祸。尚未取信，大永守正，悔恨消失。' }, { position: 6, text: '上六：赍咨涕洟，无咎。', explain: '叹息流泪，无灾祸。' }] },
  { key: '011000', name: '升', fullName: '地风升', symbol: '☷☴', upperTrigram: '坤', lowerTrigram: '巽', wuxing: '土', guaci: '升，元亨，用见大人，勿恤，南征吉。', guaciExplain: '升卦象征上升，大亨通，用来见大人，不要忧虑，南征吉利。', yaoci: [{ position: 1, text: '初六：允升，大吉。', explain: '允许上升，大吉。' }, { position: 2, text: '九二：孚乃利用禴，无咎。', explain: '有诚信则利于薄祭，无灾祸。' }, { position: 3, text: '九三：升虚邑。', explain: '上升到空旷的城邑。' }, { position: 4, text: '六四：王用亨于岐山，吉无咎。', explain: '君王在岐山祭祀，吉利无灾祸。' }, { position: 5, text: '六五：贞吉，升阶。', explain: '守正则吉，登上台阶。' }, { position: 6, text: '上六：冥升，利于不息之贞。', explain: '昏冥中上升，利于不息地守正。' }] },
  { key: '010100', name: '困', fullName: '泽水困', symbol: '☱☵', upperTrigram: '兑', lowerTrigram: '坎', wuxing: '金', guaci: '困，亨，贞，大人吉，无咎，有言不信。', guaciExplain: '困卦象征困穷，亨通，守正，大人吉利，无灾祸，有言语不被相信。', yaoci: [{ position: 1, text: '初六：臀困于株木，入于幽谷，三岁不见。', explain: '臀部困在枯木上，进入幽深的山谷，三年不见。' }, { position: 2, text: '九二：困于酒食，朱绂方来，利用享祀，征凶，无咎。', explain: '困于酒食，红色祭服刚来，利于祭祀，出征凶险，无灾祸。' }, { position: 3, text: '六三：困于石，据于蒺藜，入于其宫，不见其妻，凶。', explain: '困在石头上，依靠在蒺藜上，进入宫室，不见妻子，凶险。' }, { position: 4, text: '九四：来徐徐，困于金车，吝，有终。', explain: '缓缓而来，困在铜车中，遗憾，但有结果。' }, { position: 5, text: '九五：劓刖，困于赤绂，乃徐有说，利用祭祀。', explain: '割鼻断足，困于红色祭服，慢慢解脱，利于祭祀。' }, { position: 6, text: '上六：困于葛藟，于臲卼，曰动悔。有悔，征吉。', explain: '困在葛藤中，不安定，说动则有悔。有悔改，出征吉利。' }] },
  { key: '011010', name: '井', fullName: '水风井', symbol: '☵☴', upperTrigram: '坎', lowerTrigram: '巽', wuxing: '水', guaci: '井，改邑不改井，无丧无得，往来井井。', guaciExplain: '井卦象征水井，改迁城邑不改水井，无丧失无获得，来来往往从井中取水。', yaoci: [{ position: 1, text: '初六：井泥不食，旧井无禽。', explain: '井中泥泞不能饮用，旧井没有禽兽。' }, { position: 2, text: '九二：井谷射鲋，瓮敝漏。', explain: '井底射小鱼，水瓮破漏。' }, { position: 3, text: '九三：井渫不食，为我心恻，可用汲，王明，并受其福。', explain: '井水清洁却不被饮用，使我心痛，可以汲取，君王英明，共同享受福祉。' }, { position: 4, text: '六四：井甃，无咎。', explain: '修砌井壁，无灾祸。' }, { position: 5, text: '九五：井冽，寒泉食。', explain: '井水清冽，寒泉可饮。' }, { position: 6, text: '上六：井收勿幕，有孚元吉。', explain: '井水收起不要盖上，有诚信则大吉。' }] },
  { key: '101110', name: '革', fullName: '泽火革', symbol: '☱☲', upperTrigram: '兑', lowerTrigram: '离', wuxing: '金', guaci: '革，已日乃孚，元亨利贞，悔亡。', guaciExplain: '革卦象征变革，到已日才有诚信，大亨通利于守正，悔恨消失。', yaoci: [{ position: 1, text: '初九：巩用黄牛之革。', explain: '用黄牛皮绳牢固捆绑。' }, { position: 2, text: '六二：已日乃革之，征吉，无咎。', explain: '到已日才变革，出征吉利，无灾祸。' }, { position: 3, text: '九三：征凶，贞厉，革言三就，有孚。', explain: '出征凶险，守正防危，变革之言三次成就，有诚信。' }, { position: 4, text: '九四：悔亡，有孚改命，吉。', explain: '悔恨消失，有诚信地改变命令，吉利。' }, { position: 5, text: '九五：大人虎变，未占有孚。', explain: '大人如虎般变革，不必占卜已有诚信。' }, { position: 6, text: '上六：君子豹变，小人革面，征凶，居贞吉。', explain: '君子如豹般变革，小人改变面色，出征凶险，安居守正则吉。' }] },
  { key: '011101', name: '鼎', fullName: '火风鼎', symbol: '☲☴', upperTrigram: '离', lowerTrigram: '巽', wuxing: '火', guaci: '鼎，元吉，亨。', guaciExplain: '鼎卦象征鼎器，大吉，亨通。革故鼎新。', yaoci: [{ position: 1, text: '初六：鼎颠趾，利出否，得妾以其子，无咎。', explain: '鼎足颠倒，利于清除废物，得到妾因为她的儿子，无灾祸。' }, { position: 2, text: '九二：鼎有实，我仇有疾，不我能即，吉。', explain: '鼎中有食物，我的配偶有病，不能到我这里，吉利。' }, { position: 3, text: '九三：鼎耳革，其行塞，雉膏不食，方雨亏悔，终吉。', explain: '鼎耳被革除，移动受阻，雉膏不能食用，正下雨减损悔恨，最终吉利。' }, { position: 4, text: '九四：鼎折足，覆公餗，其形渥，凶。', explain: '鼎足折断，倾覆公侯的美食，其形状狼藉，凶险。' }, { position: 5, text: '六五：鼎黄耳金铉，利贞。', explain: '鼎有黄色耳朵和铜铉，利于守正。' }, { position: 6, text: '上九：鼎玉铉，大吉，无不利。', explain: '鼎有玉铉，大吉，无不顺利。' }] },
  { key: '100100', name: '震', fullName: '震为雷', symbol: '☳☳', upperTrigram: '震', lowerTrigram: '震', wuxing: '木', guaci: '震，亨。震来虩虩，笑言哑哑。震惊百里，不丧匕鬯。', guaciExplain: '震卦象征震动，亨通。雷声来时恐惧，后来笑语。震惊百里，不丢失祭祀的勺子和酒。', yaoci: [{ position: 1, text: '初九：震来虩虩，后笑言哑哑，吉。', explain: '雷声来时恐惧，后来笑语，吉利。' }, { position: 2, text: '六二：震来厉，亿丧贝，跻于九陵，勿逐，七日得。', explain: '雷声来时有危险，大量丧失财物，登上九陵，不要追，七天后得到。' }, { position: 3, text: '六三：震苏苏，震行无眚。', explain: '雷声惊惧不安，雷行无灾祸。' }, { position: 4, text: '九四：震遂泥。', explain: '雷声坠入泥中。' }, { position: 5, text: '六五：震往来厉，亿无丧，有事。', explain: '雷声往来有危险，大量没有丧失，有事要做。' }, { position: 6, text: '上六：震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言。', explain: '雷声恐惧，目光惊慌，出征凶险。雷不在自己身上，在邻居身上，无灾祸。婚姻有言语。' }] },
  { key: '001001', name: '艮', fullName: '艮为山', symbol: '☶☶', upperTrigram: '艮', lowerTrigram: '艮', wuxing: '土', guaci: '艮其背，不获其身，行其庭，不见其人，无咎。', guaciExplain: '艮卦象征停止，止于背后，不见自身，走在庭院中不见其人，无灾祸。', yaoci: [{ position: 1, text: '初六：艮其趾，无咎，利永贞。', explain: '止住脚趾，无灾祸，利于长久守正。' }, { position: 2, text: '六二：艮其腓，不拯其随，其心不快。', explain: '止住小腿，不能拯救跟随者，心中不快。' }, { position: 3, text: '九三：艮其限，列其夤，厉薰心。', explain: '止住腰部，脊肉分裂，危险如烟熏心。' }, { position: 4, text: '六四：艮其身，无咎。', explain: '止住身体，无灾祸。' }, { position: 5, text: '六五：艮其辅，言有序，悔亡。', explain: '止住面颊，言语有序，悔恨消失。' }, { position: 6, text: '上九：敦艮，吉。', explain: '敦厚地止住，吉利。' }] },
  { key: '110010', name: '渐', fullName: '风山渐', symbol: '☴☶', upperTrigram: '巽', lowerTrigram: '艮', wuxing: '木', guaci: '渐，女归吉，利贞。', guaciExplain: '渐卦象征渐进，女子出嫁吉利，利于守正。循序渐进。', yaoci: [{ position: 1, text: '初六：鸿渐于干，小子厉，有言，无咎。', explain: '鸿雁渐进到水边，小子有危险，有言语，无灾祸。' }, { position: 2, text: '六二：鸿渐于磐，饮食衎衎，吉。', explain: '鸿雁渐进到磐石上，饮食和乐，吉利。' }, { position: 3, text: '九三：鸿渐于陆，夫征不复，妇孕不育，凶，利御寇。', explain: '鸿雁渐进到高地，丈夫出征不归，妇人怀孕不育，凶险，利于抵御强盗。' }, { position: 4, text: '六四：鸿渐于木，或得其桷，无咎。', explain: '鸿雁渐进到树上，或许得到平枝，无灾祸。' }, { position: 5, text: '九五：鸿渐于陵，妇三岁不孕，终莫之胜，吉。', explain: '鸿雁渐进到丘陵，妇人三年不孕，最终没有人能胜过，吉利。' }, { position: 6, text: '上九：鸿渐于陆，其羽可用为仪，吉。', explain: '鸿雁渐进到高地，它的羽毛可用作仪饰，吉利。' }] },
  { key: '010110', name: '归妹', fullName: '雷泽归妹', symbol: '☳☱', upperTrigram: '震', lowerTrigram: '兑', wuxing: '木', guaci: '归妹，征凶，无攸利。', guaciExplain: '归妹卦象征少女出嫁，出征凶险，无所利。', yaoci: [{ position: 1, text: '初九：归妹以娣，跛能履，征吉。', explain: '少女以陪嫁身份出嫁，跛脚能走，出征吉利。' }, { position: 2, text: '九二：眇能视，利幽人之贞。', explain: '独眼能看，利于隐士守正。' }, { position: 3, text: '六三：归妹以须，反归以娣。', explain: '少女以姐姐身份出嫁，回来以陪嫁身份。' }, { position: 4, text: '九四：归妹愆期，迟归有时。', explain: '少女出嫁延误日期，迟嫁有时机。' }, { position: 5, text: '六五：帝乙归妹，其君之袂，不如其娣之袂良，月几望，吉。', explain: '帝乙嫁女，其君的衣袖不如陪嫁的衣袖好，月亮近圆，吉利。' }, { position: 6, text: '上六：女承筐无实，士刲羊无血，无攸利。', explain: '女子捧筐没有实物，男子宰羊没有血，无所利。' }] },
  { key: '110100', name: '丰', fullName: '雷火丰', symbol: '☳☲', upperTrigram: '震', lowerTrigram: '离', wuxing: '木', guaci: '丰，亨，王假之，勿忧，宜日中。', guaciExplain: '丰卦象征丰盛，亨通，君王来到，不要忧虑，宜在日中。', yaoci: [{ position: 1, text: '初九：遇其配主，虽旬无咎，往有尚。', explain: '遇到匹配的主人，虽然势均力敌也无灾祸，前往会得到崇尚。' }, { position: 2, text: '六二：丰其蔀，日中见斗，往得疑疾，有孚发若，吉。', explain: '遮蔽广大，日中看到北斗星，前往得疑疾，有诚信则光明，吉利。' }, { position: 3, text: '九三：丰其沛，日中见沫，折其右肱，无咎。', explain: '遮蔽更大，日中看到小星，折断右臂，无灾祸。' }, { position: 4, text: '九四：丰其蔀，日中见斗，遇其夷主，吉。', explain: '遮蔽广大，日中看到北斗星，遇到平辈主人，吉利。' }, { position: 5, text: '六五：来章，有庆誉，吉。', explain: '来显文采，有喜庆赞誉，吉利。' }, { position: 6, text: '上六：丰其屋，蔀其家，窥其户，阒其无人，三岁不见，凶。', explain: '房屋广大，遮蔽其家，从门缝看，寂静无人，三年不见，凶险。' }] },
  { key: '001101', name: '旅', fullName: '火山旅', symbol: '☲☶', upperTrigram: '离', lowerTrigram: '艮', wuxing: '火', guaci: '旅，小亨，旅贞吉。', guaciExplain: '旅卦象征旅行，小亨通，旅行守正则吉。', yaoci: [{ position: 1, text: '初六：旅琐琐，斯其所取灾。', explain: '旅行中琐碎小气，这是自取灾祸。' }, { position: 2, text: '六二：旅即次，怀其资，得童仆贞。', explain: '旅行到客舍，怀揣资财，得到忠贞的童仆。' }, { position: 3, text: '九三：旅焚其次，丧其童仆，贞厉。', explain: '旅行中客舍被焚，丧失童仆，守正防危。' }, { position: 4, text: '九四：旅于处，得其资斧，我心不快。', explain: '旅行在住处，得到资财斧头，心中不快。' }, { position: 5, text: '六五：射雉一矢亡，终以誉命。', explain: '射雉鸡损失一支箭，最终获得赞誉和封命。' }, { position: 6, text: '上九：鸟焚其巢，旅人先笑后号咷。丧牛于易，凶。', explain: '鸟巢被焚，旅人先笑后哭。在田边丢失牛，凶险。' }] },
  { key: '011011', name: '巽', fullName: '巽为风', symbol: '☴☴', upperTrigram: '巽', lowerTrigram: '巽', wuxing: '木', guaci: '巽，小亨，利有攸往，利见大人。', guaciExplain: '巽卦象征顺从，小亨通，利于前往，利于见到大人。', yaoci: [{ position: 1, text: '初六：进退，利武人之贞。', explain: '进退不定，利于武人守正。' }, { position: 2, text: '九二：巽在床下，用史巫纷若，吉无咎。', explain: '顺从到床下，用史巫纷繁祭祀，吉利无灾祸。' }, { position: 3, text: '九三：频巽，吝。', explain: '频繁地顺从，遗憾。' }, { position: 4, text: '六四：悔亡，田获三品。', explain: '悔恨消失，田猎获得三品。' }, { position: 5, text: '九五：贞吉悔亡，无不利。无初有终，先庚三日，后庚三日，吉。', explain: '守正则吉悔恨消失，无不顺利。开始不好最终好，先庚三日，后庚三日，吉利。' }, { position: 6, text: '上九：巽在床下，丧其资斧，贞凶。', explain: '顺从到床下，丧失资财斧头，守正亦凶。' }] },
  { key: '100100', name: '兑', fullName: '兑为泽', symbol: '☱☱', upperTrigram: '兑', lowerTrigram: '兑', wuxing: '金', guaci: '兑，亨，利贞。', guaciExplain: '兑卦象征喜悦，亨通，利于守正。', yaoci: [{ position: 1, text: '初九：和兑，吉。', explain: '和悦，吉利。' }, { position: 2, text: '九二：孚兑，吉，悔亡。', explain: '诚信喜悦，吉利，悔恨消失。' }, { position: 3, text: '六三：来兑，凶。', explain: '前来求悦，凶险。' }, { position: 4, text: '九四：商兑，未宁，介疾有喜。', explain: '商议喜悦，尚未安宁，疾病有喜。' }, { position: 5, text: '九五：孚于剥，有厉。', explain: '诚信于剥损，有危险。' }, { position: 6, text: '上六：引兑。', explain: '引导喜悦。' }] },
  { key: '010011', name: '涣', fullName: '风水涣', symbol: '☴☵', upperTrigram: '巽', lowerTrigram: '坎', wuxing: '木', guaci: '涣，亨。王假有庙，利涉大川，利贞。', guaciExplain: '涣卦象征涣散，亨通。君王来到宗庙，利于渡大河，利于守正。', yaoci: [{ position: 1, text: '初六：用拯马壮，吉。', explain: '用壮马拯救，吉利。' }, { position: 2, text: '九二：涣奔其机，悔亡。', explain: '涣散奔向几案，悔恨消失。' }, { position: 3, text: '六三：涣其躬，无悔。', explain: '涣散自身，没有悔恨。' }, { position: 4, text: '六四：涣其群，元吉。涣有丘，匪夷所思。', explain: '涣散群体，大吉。涣散有山丘，不是常人能想到的。' }, { position: 5, text: '九五：涣汗其大号，涣王居，无咎。', explain: '涣散如出汗大号令，涣散君王的居所，无灾祸。' }, { position: 6, text: '上九：涣其血，去逖出，无咎。', explain: '涣散血光，远离而出，无灾祸。' }] },
  { key: '110010', name: '节', fullName: '水泽节', symbol: '☵☱', upperTrigram: '坎', lowerTrigram: '兑', wuxing: '水', guaci: '节，亨。苦节不可贞。', guaciExplain: '节卦象征节制，亨通。但苦于节制不可守正。', yaoci: [{ position: 1, text: '初九：不出户庭，无咎。', explain: '不出门庭，无灾祸。' }, { position: 2, text: '九二：不出门庭，凶。', explain: '不出门庭，凶险。' }, { position: 3, text: '六三：不节若，则嗟若，无咎。', explain: '不节制，就会叹息，无灾祸。' }, { position: 4, text: '六四：安节，亨。', explain: '安于节制，亨通。' }, { position: 5, text: '九五：甘节，吉，往有尚。', explain: '甘于节制，吉利，前往会得到崇尚。' }, { position: 6, text: '上六：苦节，贞凶，悔亡。', explain: '苦于节制，守正亦凶，悔恨消失。' }] },
  { key: '110011', name: '中孚', fullName: '风泽中孚', symbol: '☴☱', upperTrigram: '巽', lowerTrigram: '兑', wuxing: '木', guaci: '中孚，豚鱼吉，利涉大川，利贞。', guaciExplain: '中孚卦象征内心诚信，用豚鱼祭祀吉利，利于渡大河，利于守正。', yaoci: [{ position: 1, text: '初九：虞吉，有他不燕。', explain: '安守则吉，有他念则不安。' }, { position: 2, text: '九二：鸣鹤在阴，其子和之，我有好爵，吾与尔靡之。', explain: '鹤在树荫中鸣叫，小鹤应和，我有好酒，与你共享。' }, { position: 3, text: '六三：得敌，或鼓或罢，或泣或歌。', explain: '遇到对手，或击鼓或停止，或哭泣或歌唱。' }, { position: 4, text: '六四：月几望，马匹亡，无咎。', explain: '月亮近圆，马匹丢失，无灾祸。' }, { position: 5, text: '九五：有孚挛如，无咎。', explain: '有诚信紧密相连，无灾祸。' }, { position: 6, text: '上九：翰音登于天，贞凶。', explain: '鸡鸣之声升上天空，守正亦凶。' }] },
  { key: '001100', name: '小过', fullName: '雷山小过', symbol: '☳☶', upperTrigram: '震', lowerTrigram: '艮', wuxing: '木', guaci: '小过，亨，利贞，可小事，不可大事。飞鸟遗之音，不宜上宜下，大吉。', guaciExplain: '小过卦象征小有过越，亨通，利于守正，可做小事，不可做大事。', yaoci: [{ position: 1, text: '初六：飞鸟以凶。', explain: '飞鸟带来凶险。' }, { position: 2, text: '六二：过其祖，遇其妣，不及其君，遇其臣，无咎。', explain: '越过祖父，遇到祖母，不及君王，遇到臣子，无灾祸。' }, { position: 3, text: '九三：弗过防之，从或戕之，凶。', explain: '不过分防备，跟从或许被杀害，凶险。' }, { position: 4, text: '九四：无咎，弗过遇之。往厉必戒，勿用永贞。', explain: '无灾祸，不过分而遇到。前往危险必须戒备，不要永远守正。' }, { position: 5, text: '六五：密云不雨，自我西郊，公弋取彼在穴。', explain: '密云不雨，从我们西郊而来，公侯射取穴中的猎物。' }, { position: 6, text: '上六：弗遇过之，飞鸟离之，凶，是谓灾眚。', explain: '不遇到而越过，飞鸟被网住，凶险，这就是灾祸。' }] },
  { key: '101010', name: '既济', fullName: '水火既济', symbol: '☵☲', upperTrigram: '坎', lowerTrigram: '离', wuxing: '水', guaci: '既济，亨小，利贞，初吉终乱。', guaciExplain: '既济卦象征已经完成，小亨通，利于守正，开始吉利最终混乱。', yaoci: [{ position: 1, text: '初九：曳其轮，濡其尾，无咎。', explain: '拖住车轮，沾湿尾巴，无灾祸。' }, { position: 2, text: '六二：妇丧其茀，勿逐，七日得。', explain: '妇人丢失头饰，不要追，七天后得到。' }, { position: 3, text: '九三：高宗伐鬼方，三年克之，小人勿用。', explain: '高宗征伐鬼方，三年攻克，不要任用小人。' }, { position: 4, text: '六四：繻有衣袽，终日戒。', explain: '华服变成破衣，整天戒备。' }, { position: 5, text: '九五：东邻杀牛，不如西邻之禴祭，实受其福。', explain: '东邻杀牛祭祀，不如西邻的薄祭，实际受到福佑。' }, { position: 6, text: '上六：濡其首，厉。', explain: '沾湿头部，危险。' }] },
  { key: '010101', name: '未济', fullName: '火水未济', symbol: '☲☵', upperTrigram: '离', lowerTrigram: '坎', wuxing: '火', guaci: '未济，亨，小狐汔济，濡其尾，无攸利。', guaciExplain: '未济卦象征尚未完成，亨通，小狐狸快要渡过河，沾湿尾巴，无所利。', yaoci: [{ position: 1, text: '初六：濡其尾，吝。', explain: '沾湿尾巴，遗憾。' }, { position: 2, text: '九二：曳其轮，贞吉。', explain: '拖住车轮，守正则吉。' }, { position: 3, text: '六三：未济，征凶，利涉大川。', explain: '尚未完成，出征凶险，利于渡大河。' }, { position: 4, text: '九四：贞吉，悔亡，震用伐鬼方，三年有赏于大国。', explain: '守正则吉悔恨消失，用武力征伐鬼方，三年后在大国获得赏赐。' }, { position: 5, text: '六五：贞吉，无悔，君子之光，有孚，吉。', explain: '守正则吉没有悔恨，君子的光辉，有诚信，吉利。' }, { position: 6, text: '上九：有孚于饮酒，无咎，濡其首，有孚失是。', explain: '有诚信地饮酒，无灾祸，沾湿头部，有诚信但失去正道。' }] },
]

export const ALL_GUA_DATA: GuaData[] = [...GUA_64, ...REMAINING_GUAS]

export function getGuaByKey(key: string): GuaData | undefined {
  return ALL_GUA_DATA.find(g => g.key === key)
}

export function getGuaByTrigrams(upper: string, lower: string): GuaData | undefined {
  return ALL_GUA_DATA.find(g => g.upperTrigram === upper && g.lowerTrigram === lower)
}

export function getTrigramKey(yao: [number, number, number]): string {
  return yao.map(v => v === 1 ? '1' : '0').join('')
}

export function getGuaKey(yaos: [number, number, number, number, number, number]): string {
  const lower = yaos.slice(0, 3).map(v => v === 1 ? '1' : '0').join('')
  const upper = yaos.slice(3, 6).map(v => v === 1 ? '1' : '0').join('')
  return lower + upper
}
